import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Runtime {
  id: string;
  event_registration_id: string;
  event_route_id: string;
  duration_seconds: number;
  position?: number;
  recorded_by: string;
  createdAt?: string;
  updatedAt?: string;

  eventRoute?: {
    id: string;
    event_id: string;
    route_id: string;
  };
}

@Injectable({
  providedIn: 'root',
})
export class RuntimeService {
  private apiUrl = 'http://localhost:3000/api/runtimes';

  constructor(private http: HttpClient) {}

  //  Alle Laufzeiten
  getAll(): Observable<Runtime[]> {
    return this.http.get<Runtime[]>(this.apiUrl);
  }

  //  Laufzeit per ID
  getById(id: string): Observable<Runtime> {
    return this.http.get<Runtime>(`${this.apiUrl}/${id}`);
  }

  //  Laufzeit zu Anmeldung
  getByRegistration(registrationId: string): Observable<Runtime> {
    return this.http.get<Runtime>(
      `${this.apiUrl}/registration/${registrationId}`
    );
  }

  // ➕ Neue Laufzeit
  create(data: {
    event_registration_id: string;
    event_route_id: string;
    duration_seconds: number;
  }): Observable<Runtime> {
    return this.http.post<Runtime>(this.apiUrl, data);
  }

  // ✏️ Laufzeit aktualisieren
  update(id: string, data: {
    event_registration_id: string;
    event_route_id: string;
    duration_seconds: number;
  }): Observable<Runtime> {
    return this.http.put<Runtime>(`${this.apiUrl}/${id}`, data);
  }

  // ❌ Löschen
  delete(id: string): Observable<any> {
    return this.http.delete(`${this.apiUrl}/${id}`);
  }
}

import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Runtime {
  id: string;
  participant_id: string;
  event_route_id: string;
  duration_seconds: number;
  position?: number | null;
  recorded_by?: string;
  createdAt?: string;
  updatedAt?: string;

  eventRoute?: {
    id: string;
    event_id: string;
    route_id: string;
  };

  participant?: {
    id: string;
    registration_id: string;
    person_id: string;
    registration?: {
      id: string;
      event_id: string;
    };
  };
}

export interface RuntimeCreatePayload {
  participant_id: string;
  event_route_id: string;
  duration_seconds: number;
}

export interface RuntimeUpdatePayload {
  duration_seconds: number;
}

@Injectable({
  providedIn: 'root',
})
export class RuntimeService {
  private apiUrl = 'http://localhost:3000/api/runtimes';

  constructor(private http: HttpClient) {}

  //  Alle Laufzeiten
  getAll(): Observable<Runtime[]> {
    return this.http.get<Runtime[]>(this.apiUrl);
  }

  //  Laufzeit per ID
  getById(id: string): Observable<Runtime> {
    return this.http.get<Runtime>(`${this.apiUrl}/${id}`);
  }

  //  Laufzeiten eines Events
  getByEvent(eventId: string): Observable<Runtime[]> {
    return this.http.get<Runtime[]>(`${this.apiUrl}/event/${eventId}`);
  }

  // ➕ Neue Laufzeit
  create(data: RuntimeCreatePayload): Observable<Runtime> {
    return this.http.post<Runtime>(this.apiUrl, data);
  }

  // ✏️ Laufzeit aktualisieren
  update(id: string, data: RuntimeUpdatePayload): Observable<Runtime> {
    return this.http.put<Runtime>(`${this.apiUrl}/${id}`, data);
  }

  // ❌ Löschen
  delete(id: string): Observable<any> {
    return this.http.delete(`${this.apiUrl}/${id}`);
  }
}

import { Component, OnInit, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { forkJoin } from 'rxjs';

import { EventService, EventInterface } from '../../core/services/event.service';
import { RouteService, Route } from '../../core/services/route.service';
import { EventRegistrationService } from '../../core/services/event-registration.service';
import { RuntimeService, Runtime } from '../../core/services/runtime.service';

interface ParticipantRow {
  registrationId: string;
  participantId: string;
  name: string;
}

@Component({
  selector: 'app-race-results',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './race-results.html',
  styleUrls: ['./race-results.css']
})
export class RaceResults implements OnInit {

  private eventService = inject(EventService);
  private routeService = inject(RouteService);
  private regService = inject(EventRegistrationService);
  private runtimeService = inject(RuntimeService);

  // STATE
  events = signal<EventInterface[]>([]);
  selectedEventId = signal<string | null>(null);

  routes = signal<Route[]>([]);
  participants = signal<ParticipantRow[]>([]);
  runtimes = signal<Runtime[]>([]);

  loading = signal(false);
  error = signal<string | null>(null);

  // INIT
  ngOnInit() {
    this.loadEvents();
  }

  private loadEvents() {
    this.loading.set(true);
    this.error.set(null);

    this.eventService.getAll().subscribe({
      next: data => {
        this.events.set(data);
        this.loading.set(false);
      },
      error: () => {
        this.error.set('Events konnten nicht geladen werden.');
        this.loading.set(false);
      }
    });
  }

  onSelectEvent(eventId: string) {
    if (!eventId) {
      this.selectedEventId.set(null);
      this.routes.set([]);
      this.participants.set([]);
      this.runtimes.set([]);
      return;
    }

    this.selectedEventId.set(eventId);
    this.loadEventData(eventId);
  }

  private loadEventData(eventId: string) {
    this.loading.set(true);
    this.error.set(null);

    forkJoin({
      routes: this.routeService.getByEvent(eventId),
      regs: this.regService.getGroupByEvent(eventId),
      runtimes: this.runtimeService.getAll()
    }).subscribe({
      next: ({ routes, regs, runtimes }) => {
        this.routes.set(routes ?? []);
        console.log('Registrations:', regs);

        const flat: ParticipantRow[] = (regs ?? []).flatMap(reg =>
          (reg.participants ?? []).map(p => ({
            registrationId: reg.id!,
            participantId: p.id!,
            name: p.person
              ? `${p.person.first_name} ${p.person.last_name}`
              : 'Unbekannt'
          }))
        );

        this.participants.set(flat);
        this.runtimes.set(runtimes ?? []);
        this.loading.set(false);
      },
      error: (err) => {
        // Wenn du hier wieder 403 siehst: Interceptor fehlt oder Token falsch.
        console.error(err);
        this.error.set('Daten konnten nicht geladen werden.');
        this.loading.set(false);
      }
    });
  }

  // RUNTIME HELPERS
  private findRuntime(regId: string, routeId: string): Runtime | undefined {
    return this.runtimes().find(r =>
      r.event_registration_id === regId &&
      r.eventRoute?.route_id === routeId
    );
  }

  getTimeValue(regId: string, routeId: string): string {
    const rt = this.findRuntime(regId, routeId);
    if (!rt) return '';
    return this.secondsToHms(rt.duration_seconds);
  }

  /**
   * Speichern beim Blur.
   * - Wenn Wert leer: optional löschen (wenn Backend delete anbietet) ODER ignorieren
   * - Wenn Runtime existiert: update
   * - Sonst: create
   */
  onTimeBlur(regId: string, routeId: string, raw: string) {
    const value = (raw ?? '').trim();

    // Leer -> wir lassen es leer. (Wenn du löschen willst: unten Kommentar lesen)
    if (!value) return;

    // "HH:MM" oder "HH:MM:SS" akzeptieren
    const seconds = this.hmsToSeconds(value);
    if (seconds === null) return;

    const existing = this.findRuntime(regId, routeId);

    if (existing?.id) {
      const payload: Runtime = { ...existing, duration_seconds: seconds };

      this.runtimeService.update(existing.id, payload).subscribe({
        next: updated => this.replaceRuntime(updated),
        error: err => console.error('Update Runtime fehlgeschlagen', err)
      });
    } else {
      const payload: Partial<Runtime> = {
        event_registration_id: regId,
        event_route_id: routeId,
        duration_seconds: seconds
      };

      this.runtimeService.create(payload as Runtime).subscribe({
        next: created => this.runtimes.update(list => [...list, created]),
        error: err => console.error('Create Runtime fehlgeschlagen', err)
      });
    }
  }

  private replaceRuntime(updated: Runtime) {
    this.runtimes.update(list => list.map(r => (r.id === updated.id ? updated : r)));
  }

  totalTime(regId: string): string {
    const routes = this.routes();
    if (!routes.length) return '—';

    let total = 0;
    for (const r of routes) {
      const rt = this.findRuntime(regId, r.id);
      if (!rt) return '—';
      total += rt.duration_seconds;
    }
    return this.secondsToHms(total);
  }

  // TIME UTILS
  private secondsToHms(total: number): string {
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    return [h, m, s].map(v => String(v).padStart(2, '0')).join(':');
  }

  private hmsToSeconds(hms: string): number | null {
    // erlaubt: "HH:MM" oder "HH:MM:SS"
    const parts = hms.split(':').map(p => p.trim());
    if (parts.length < 2 || parts.length > 3) return null;

    const h = Number(parts[0]);
    const m = Number(parts[1]);
    const s = parts.length === 3 ? Number(parts[2]) : 0;

    if ([h, m, s].some(n => Number.isNaN(n))) return null;
    if (h < 0 || m < 0 || m > 59 || s < 0 || s > 59) return null;

    return h * 3600 + m * 60 + s;
  }
}

import { Component, OnInit, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { forkJoin } from 'rxjs';

import { EventService, EventInterface } from '../../core/services/event.service';
import { RouteService, Route } from '../../core/services/route.service';
import { EventRegistrationService } from '../../core/services/event-registration.service';
import {
  RuntimeService,
  Runtime,
  RuntimeCreatePayload,
  RuntimeUpdatePayload
} from '../../core/services/runtime.service';

interface ParticipantRow {
  participantId: string;
  name: string;
}

@Component({
  selector: 'app-race-results',
  standalone: true,
  imports: [CommonModule, FormsModule],
  templateUrl: './race-results.html',
  styleUrls: ['./race-results.css']
})
export class RaceResults implements OnInit {

  private eventService = inject(EventService);
  private routeService = inject(RouteService);
  private regService = inject(EventRegistrationService);
  private runtimeService = inject(RuntimeService);

  // STATE
  events = signal<EventInterface[]>([]);
  selectedEventId = signal<string | null>(null);

  routes = signal<Route[]>([]);
  participants = signal<ParticipantRow[]>([]);
  runtimes = signal<Runtime[]>([]);

  loading = signal(false);
  error = signal<string | null>(null);
  timeInputError = signal<string | null>(null);

  // INIT
  ngOnInit() {
    this.loadEvents();
  }

  private loadEvents() {
    this.loading.set(true);
    this.error.set(null);
    this.timeInputError.set(null);

    this.eventService.getAll().subscribe({
      next: data => {
        this.events.set(data);
        this.loading.set(false);
      },
      error: () => {
        this.error.set('Events konnten nicht geladen werden.');
        this.loading.set(false);
      }
    });
  }

  onSelectEvent(eventId: string) {
    if (!eventId) {
      this.selectedEventId.set(null);
      this.routes.set([]);
      this.participants.set([]);
      this.runtimes.set([]);
      this.timeInputError.set(null);
      return;
    }

    this.selectedEventId.set(eventId);
    this.loadEventData(eventId);
  }

  private loadEventData(eventId: string) {
    this.loading.set(true);
    this.error.set(null);
    this.timeInputError.set(null);

    forkJoin({
      routes: this.routeService.getByEvent(eventId),
      regs: this.regService.getGroupByEvent(eventId),
      runtimes: this.runtimeService.getByEvent(eventId)
    }).subscribe({
      next: ({ routes, regs, runtimes }) => {
        this.routes.set(routes ?? []);

        const flat: ParticipantRow[] = (regs ?? []).flatMap(reg =>
          (reg.participants ?? []).map(p => ({
            participantId: p.id!,
            name: p.person
              ? `${p.person.first_name} ${p.person.last_name}`
              : 'Unbekannt'
          }))
        );

        this.participants.set(flat);
        this.runtimes.set(runtimes ?? []);
        this.loading.set(false);
      },
      error: (err) => {
        // Wenn du hier wieder 403 siehst: Interceptor fehlt oder Token falsch.
        console.error(err);
        this.error.set('Daten konnten nicht geladen werden.');
        this.loading.set(false);
      }
    });
  }

  // RUNTIME HELPERS
  private findRuntime(participantId: string, routeId: string): Runtime | undefined {
    return this.runtimes().find(r =>
      r.participant_id === participantId &&
      r.eventRoute?.route_id === routeId
    );
  }

  getTimeValue(participantId: string, routeId: string): string {
    const rt = this.findRuntime(participantId, routeId);
    if (!rt) return '';
    return this.secondsToHms(rt.duration_seconds);
  }

  /**
   * Speichern beim Blur.
   * - Wenn Wert leer: optional löschen (wenn Backend delete anbietet) ODER ignorieren
   * - Wenn Runtime existiert: update
   * - Sonst: create
   */
  onTimeBlur(participantId: string, routeId: string, raw: string) {
    const value = (raw ?? '').trim();
    this.timeInputError.set(null);

    // Leer -> wir lassen es leer. (Wenn du löschen willst: unten Kommentar lesen)
    if (!value) return;

    // "HH:MM" oder "HH:MM:SS" akzeptieren (als Dauer, nicht als Uhrzeit)
    const seconds = this.hmsToSeconds(value);
    if (seconds === null) {
      this.timeInputError.set('Ungültiges Zeitformat. Bitte HH:MM oder HH:MM:SS als Dauer eingeben.');
      return;
    }

    const existing = this.findRuntime(participantId, routeId);

    if (existing?.id) {
      const payload: RuntimeUpdatePayload = { duration_seconds: seconds };

      this.runtimeService.update(existing.id, payload).subscribe({
        next: updated => {
          this.timeInputError.set(null);
          this.replaceRuntime(updated);
        },
        error: err => console.error('Update Runtime fehlgeschlagen', err)
      });
    } else {
      const payload: RuntimeCreatePayload = {
        participant_id: participantId,
        event_route_id: routeId,
        duration_seconds: seconds
      };

      this.runtimeService.create(payload).subscribe({
        next: created => {
          this.timeInputError.set(null);
          this.runtimes.update(list => [...list, created]);
        },
        error: err => console.error('Create Runtime fehlgeschlagen', err)
      });
    }
  }

  private replaceRuntime(updated: Runtime) {
    this.runtimes.update(list => list.map(r => (r.id === updated.id ? updated : r)));
  }

  totalTime(participantId: string): string {
    const routes = this.routes();
    if (!routes.length) return '—';

    let total = 0;
    for (const r of routes) {
      const rt = this.findRuntime(participantId, r.id);
      if (!rt) return '—';
      total += rt.duration_seconds;
    }
    return this.secondsToHms(total);
  }

  // TIME UTILS
  private secondsToHms(total: number): string {
    const h = Math.floor(total / 3600);
    const m = Math.floor((total % 3600) / 60);
    const s = total % 60;
    return [h, m, s].map(v => String(v).padStart(2, '0')).join(':');
  }

  private hmsToSeconds(hms: string): number | null {
    // erlaubt: "HH:MM" oder "HH:MM:SS"
    const parts = hms.split(':').map(p => p.trim());
    if (parts.length < 2 || parts.length > 3) return null;

    const h = Number(parts[0]);
    const m = Number(parts[1]);
    const s = parts.length === 3 ? Number(parts[2]) : 0;

    if ([h, m, s].some(n => Number.isNaN(n))) return null;
    if (h < 0 || m < 0 || m > 59 || s < 0 || s > 59) return null;

    return h * 3600 + m * 60 + s;
  }
}
